BEGIN;
DO $$ BEGIN IF current_user <> 'ai_mls_production_migration_operator' THEN RAISE EXCEPTION 'REL002_R3B1_MIGRATION_OPERATOR_REQUIRED'; END IF; IF to_regnamespace('app_administration') IS NOT NULL THEN RAISE EXCEPTION 'REL002_R3B1_ADMINISTRATION_SCHEMA_ALREADY_EXISTS'; END IF; END $$;
CREATE SCHEMA app_administration AUTHORIZATION ai_mls_production_migration_operator;
COMMENT ON SCHEMA app_administration IS 'REL002-R3B1-ADMINISTRATION-V1|schema_version=1|contract_fingerprint=admin-v1-9-tables';
CREATE TABLE app_administration.administration_schema (singleton_id integer PRIMARY KEY CHECK(singleton_id=1), schema_version bigint NOT NULL CHECK(schema_version=1), contract_fingerprint text NOT NULL CHECK(contract_fingerprint='admin-v1-9-tables'));
CREATE TABLE app_administration.administration_revisions (tenant_id text NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, revision bigint NOT NULL CHECK(revision>=0 AND revision<=9007199254740991), PRIMARY KEY(tenant_id,resource_type,resource_id));
CREATE TABLE app_administration.administration_resources (tenant_id text NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, version bigint NOT NULL CHECK(version>0 AND version<=9007199254740991), scope_type text NOT NULL, scope_id text NOT NULL, payload_json jsonb NOT NULL, PRIMARY KEY(tenant_id,resource_type,resource_id), FOREIGN KEY(tenant_id,resource_type,resource_id) REFERENCES app_administration.administration_revisions(tenant_id,resource_type,resource_id));
CREATE TABLE app_administration.administration_proposals (tenant_id text NOT NULL, proposal_id text NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, version bigint NOT NULL CHECK(version>0 AND version<=9007199254740991), scope_type text NOT NULL, scope_id text NOT NULL, payload_json jsonb NOT NULL, PRIMARY KEY(tenant_id,proposal_id), UNIQUE(tenant_id,proposal_id,resource_type,resource_id), FOREIGN KEY(tenant_id,resource_type,resource_id) REFERENCES app_administration.administration_revisions(tenant_id,resource_type,resource_id));
CREATE TABLE app_administration.administration_decisions (tenant_id text NOT NULL, decision_id text NOT NULL, proposal_id text NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, version bigint NOT NULL CHECK(version>0 AND version<=9007199254740991), scope_type text NOT NULL, scope_id text NOT NULL, payload_json jsonb NOT NULL, PRIMARY KEY(tenant_id,decision_id), FOREIGN KEY(tenant_id,resource_type,resource_id) REFERENCES app_administration.administration_revisions(tenant_id,resource_type,resource_id), FOREIGN KEY(tenant_id,proposal_id,resource_type,resource_id) REFERENCES app_administration.administration_proposals(tenant_id,proposal_id,resource_type,resource_id));
CREATE TABLE app_administration.administration_resource_evidence (tenant_id text NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, sequence bigint NOT NULL CHECK(sequence>0 AND sequence<=9007199254740991), payload_json jsonb NOT NULL, PRIMARY KEY(tenant_id,resource_type,resource_id,sequence), FOREIGN KEY(tenant_id,resource_type,resource_id) REFERENCES app_administration.administration_resources(tenant_id,resource_type,resource_id));
CREATE TABLE app_administration.administration_proposal_evidence (tenant_id text NOT NULL, proposal_id text NOT NULL, sequence bigint NOT NULL CHECK(sequence>0 AND sequence<=9007199254740991), payload_json jsonb NOT NULL, PRIMARY KEY(tenant_id,proposal_id,sequence), FOREIGN KEY(tenant_id,proposal_id) REFERENCES app_administration.administration_proposals(tenant_id,proposal_id));
CREATE TABLE app_administration.administration_decision_evidence (tenant_id text NOT NULL, decision_id text NOT NULL, sequence bigint NOT NULL CHECK(sequence>0 AND sequence<=9007199254740991), payload_json jsonb NOT NULL, PRIMARY KEY(tenant_id,decision_id,sequence), FOREIGN KEY(tenant_id,decision_id) REFERENCES app_administration.administration_decisions(tenant_id,decision_id));
CREATE TABLE app_administration.administration_idempotency (tenant_id text NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, idempotency_key text NOT NULL, operation text NOT NULL, fingerprint text NOT NULL, result_reference text NOT NULL, result_version bigint NOT NULL CHECK(result_version>0 AND result_version<=9007199254740991), payload_json jsonb NOT NULL, PRIMARY KEY(tenant_id,resource_type,resource_id,idempotency_key), FOREIGN KEY(tenant_id,resource_type,resource_id) REFERENCES app_administration.administration_revisions(tenant_id,resource_type,resource_id));
CREATE FUNCTION app_administration.reject_append_only_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'append-only' USING ERRCODE='55000'; END $$;
CREATE TRIGGER administration_decisions_append_only BEFORE UPDATE OR DELETE ON app_administration.administration_decisions FOR EACH ROW EXECUTE FUNCTION app_administration.reject_append_only_mutation();
CREATE TRIGGER administration_resource_evidence_append_only BEFORE UPDATE OR DELETE ON app_administration.administration_resource_evidence FOR EACH ROW EXECUTE FUNCTION app_administration.reject_append_only_mutation();
CREATE TRIGGER administration_proposal_evidence_append_only BEFORE UPDATE OR DELETE ON app_administration.administration_proposal_evidence FOR EACH ROW EXECUTE FUNCTION app_administration.reject_append_only_mutation();
CREATE TRIGGER administration_decision_evidence_append_only BEFORE UPDATE OR DELETE ON app_administration.administration_decision_evidence FOR EACH ROW EXECUTE FUNCTION app_administration.reject_append_only_mutation();
CREATE TRIGGER administration_idempotency_append_only BEFORE UPDATE OR DELETE ON app_administration.administration_idempotency FOR EACH ROW EXECUTE FUNCTION app_administration.reject_append_only_mutation();
INSERT INTO app_administration.administration_schema VALUES(1,1,'admin-v1-9-tables');
COMMIT;
